"""Self-contained accounting dashboard; rendering changes only."""
import json

def render(rows,path):
    payload=json.dumps(rows,allow_nan=False).replace('</','<\\/')
    template='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Beyond Q — DD supplier and DT power stage</title>
<style>body{font:15px system-ui;max-width:1250px;margin:25px;background:#f5f7fa;color:#193147}select{padding:7px;margin:5px}canvas{width:100%;height:340px;background:white}table{border-collapse:collapse;width:100%;margin:15px 0}td,th{padding:7px;border-bottom:1px solid #ccd;text-align:right}td:first-child,th:first-child{text-align:left}.note{padding:12px;background:#e7edf5}#detail{overflow:auto}h2{font-size:19px}</style>
<h1>Beyond Q: D-D isotope factory → D-T power stage</h1>
<p>ASSUMED SCENARIOS — G1–G5 OPEN. Source physics unchanged from v2.0. Quantities and receipts are conditional, not certified products or actual profits. Tritium decay IS included. A also consumes some born T in secondary D-T reactions.</p>
<div id="controls"><label>Modules <select id="fleet"></select></label><label>Recovery <select id="recovery"></select></label><label>Price <select id="price"></select></label><label>He-3 offtake <select id="offtake"></select></label><label>Metric <select id="metric"></select></label></div>
<div id="scope" class="note"></div><canvas id="plot"></canvas><p>Move over the plot to inspect a year.</p><div id="detail"></div>
<h2>Two-reactor accounting</h2><div id="stages"></div><div id="checks" class="note"></div>
<script>const DATA=__DATA__;
const $=id=>document.getElementById(id),fmt=v=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:3}):'UNRESOLVED';
const METRICS={He3_product_candidate_STP_L:'He-3 product candidate — STP L/year',He3_sale_candidate_STP_L:'He-3 conditional sale allocation — STP L/year',He3_unsold_bank_end_STP_L:'Unsold He-3 bank — STP L',T_A_DD_birth_kg:'A direct D-D T births — kg/year',T_B_burn_kg:'B D-T consumption — kg/year',T_decay_kg:'Campus T decay — kg/year',T_inventory_change_kg:'T inventory change — kg/year; NOT qualified surplus',T_stock_end_kg:'Campus T stock — kg',electricity_net_MWh:'Net electricity — MWh/year',electricity_import_MWh:'Gross electricity imports — MWh/year',revenue_less_known_charges_USD:'Revenue less known charges — USD/year; NOT profit',actual_profit_USD:'Actual profit — UNRESOLVED'};
for(const [id,key] of [['fleet','fleet_modules'],['recovery','He3_overall_recovery_assumed'],['price','price_case'],['offtake','offtake_case']])for(const v of [...new Set(DATA.map(r=>r[key]))])$(id).add(new Option(id==='recovery'?(100*v)+'%':v,v));
for(const [key,label] of Object.entries(METRICS))$('metric').add(new Option(label,key));$('recovery').value='0.75';
function filtered(){return DATA.filter(r=>r.fleet_modules===Number($('fleet').value)&&r.He3_overall_recovery_assumed===Number($('recovery').value)&&r.price_case===$('price').value&&r.offtake_case===$('offtake').value).sort((a,b)=>a.year-b.year)}
let current=[],geometry=null;
function show(r){if(!r)return;const table=(heads,rows)=>'<table><tr>'+heads.map(x=>'<th>'+x+'</th>').join('')+'</tr>'+rows.map(a=>'<tr>'+a.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</table>';
$('detail').innerHTML=table(['Year','He-3 candidate L','He-3 conditional sales L','Unsold bank L','T stock kg','T decay kg','Actual profit'],[[r.year,fmt(r.He3_product_candidate_STP_L),fmt(r.He3_sale_candidate_STP_L),fmt(r.He3_unsold_bank_end_STP_L),fmt(r.T_stock_end_kg),fmt(r.T_decay_kg),'UNRESOLVED']]);
$('stages').innerHTML=table(['Flow in selected year','A: D-D factory','B: D-T power'],[['Direct D-D T births (kg)',fmt(r.T_A_DD_birth_kg),'0'],['Blanket T births (kg)','0 (A0)',fmt(r.T_B_gross_breeding_kg)],['T consumed in fusion (kg)',fmt(r.T_A_secondary_DT_consumed_kg),fmt(r.T_B_burn_kg)],['A → B storage transfer (kg)',fmt(r.T_A_to_B_transfer_kg)+' out',fmt(r.T_A_to_B_transfer_kg)+' in'],['Direct He-3 births (kg)',fmt(r.He3_A_DD_birth_kg),'0'],['Plasma He-4 births (kg)',fmt(r.He4_A_secondary_DT_birth_kg),fmt(r.He4_B_DT_birth_kg)]]);
$('checks').innerHTML='Accounting checks, not physical validation. D-D He-3:T atom-birth ratio = <b>'+fmt(r.DD_He3_to_T_atom_birth_ratio)+'</b>. B gross blanket TBR = <b>'+fmt(r.B_gross_TBR_ratio)+'</b> (assumed; does not establish recovered self-sufficiency).<br>Campus T: start '+fmt(r.T_start_kg)+' + A births '+fmt(r.T_A_DD_birth_kg)+' + B breeding '+fmt(r.T_B_gross_breeding_kg)+' − A burn '+fmt(r.T_A_secondary_DT_consumed_kg)+' − B burn '+fmt(r.T_B_burn_kg)+' − decay '+fmt(r.T_decay_kg)+' − processing loss '+fmt(r.T_processing_loss_kg)+' − permeation '+fmt(r.T_permeation_kg)+' − export '+fmt(r.T_external_export_scenario_kg)+' = end '+fmt(r.T_stock_end_kg)+' kg.<br>Balance residual: '+r.T_accounting_residual_kg.toExponential(3)+' kg. Per-reactor loss allocation is not available in the parent export; no zero losses are assumed.';
}
function draw(){current=filtered();const canvas=$('plot'),dpr=window.devicePixelRatio||1,w=canvas.clientWidth||1100,h=340;canvas.width=w*dpr;canvas.height=h*dpr;const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);c.font='12px system-ui';const k=$('metric').value;
if(!current.length){c.fillText('No matching rows',80,60);geometry=null;return}const cap=current[0].He3_market_cap_STP_L_per_year_fleet;
$('scope').textContent=($('offtake').value==='fleet_cap_stress'?'Illustrative fleet-wide He-3 sales cap: '+fmt(cap)+' L/year. This is a stress assumption, NOT measured global demand.':'Full-He-3-offtake sensitivity: assumes buyers for every available sale allocation, NOT a market forecast.')+' 50% of product candidate is retained internally. T exports are separately capped and donor-bounded. Price: $'+fmt(current[0].He3_price_USD_per_STP_L)+'/L He-3; $'+fmt(current[0].T_price_USD_per_gram)+'/g T.';
const valid=current.filter(r=>typeof r[k]==='number'&&Number.isFinite(r[k]));if(!valid.length){c.fillText('UNRESOLVED — no numeric values; missing data are not zero.',80,60);geometry=null;show(current[0]);return}
const lo=Math.min(0,...valid.map(r=>r[k])),hi=Math.max(1,...valid.map(r=>r[k])),left=100,right=w-20,top=25,bottom=300;
const X=yr=>left+(yr-current[0].year)/Math.max(1,current.at(-1).year-current[0].year)*(right-left),Y=v=>bottom-(v-lo)/(hi-lo)*(bottom-top);
for(let j=0;j<=4;j++){let v=lo+(hi-lo)*j/4,y=Y(v);c.strokeStyle='#d8dfe7';c.beginPath();c.moveTo(left,y);c.lineTo(right,y);c.stroke();c.fillStyle='#193147';c.fillText(v.toLocaleString(undefined,{maximumFractionDigits:0}),2,y)}
c.strokeStyle='#247a73';c.lineWidth=2;c.beginPath();let pen=false;for(const r of current){if(typeof r[k]!=='number'){pen=false;continue}if(pen)c.lineTo(X(r.year),Y(r[k]));else c.moveTo(X(r.year),Y(r[k]));pen=true}c.stroke();c.fillText('Year '+current[0].year,left,325);c.fillText('Year '+current.at(-1).year,right-65,325);geometry={left,right};show(current.at(-1));}
for(const id of ['fleet','recovery','price','offtake','metric'])$(id).addEventListener('change',draw);
$('plot').addEventListener('mousemove',e=>{if(!geometry)return;const x=e.clientX-$('plot').getBoundingClientRect().left,f=Math.max(0,Math.min(1,(x-geometry.left)/(geometry.right-geometry.left)));show(current[Math.round(f*(current.length-1))])});window.addEventListener('resize',draw);draw();</script></html>'''
    path.write_text(template.replace('__DATA__',payload))
